<template>
  <main v-if="active" class="store-author">
    <section v-for="screen in screens" :key="screen.key">
      <header class="heading"><div><h2>提货点目录</h2><p>管理提货点资料、营业状态与回收站。店员及订单约束由服务端核验。</p></div><div class="actions"><el-button :disabled="state.busy" @click="screen.refresh">重新读取提货点</el-button><el-button v-if="canManage" type="primary" :disabled="!model.writable() || !!state.editor || (state.snapshot?.count ?? 0) >= 5000" @click="screen.create">新增提货点</el-button></div></header>
      <el-alert v-if="state.pending" title="原提货点操作结果尚未确认，新的提交已暂停" type="warning" :closable="false"><p>未找到回执仍表示结果未知。可以读取回执，或主动核对并封存原请求。</p><div class="actions"><el-button :disabled="state.busy" @click="screen.receipt">读取原回执</el-button><el-button :disabled="state.busy" @click="screen.resolve">核对并封存原请求</el-button><el-button v-if="state.retryReady && canManage" :disabled="state.busy" @click="screen.retry">原样重试</el-button></div></el-alert>
      <el-alert v-if="!canView" title="当前没有提货点查看权限" type="warning" :closable="false" />
      <el-alert v-if="state.error || state.pendingError" :title="state.error || state.pendingError" type="error" :closable="false" />
      <el-alert v-if="state.notice" :title="state.notice" type="success" :closable="false" />
      <template v-if="canView">
        <el-alert v-if="state.snapshot && !state.snapshot.write_ready" title="此环境尚未安装提货点安全写入能力，目录可查看" type="warning" :closable="false" />
        <div class="filters"><label>门店、电话或地址<input aria-label="提货点关键词" :value="state.filters.keyword" :disabled="model.viewLocked()" @input="screen.keyword(($event.target as HTMLInputElement).value)" /></label><label>目录范围<select aria-label="提货点范围" :value="state.filters.type" :disabled="model.viewLocked()" @change="screen.type(($event.target as HTMLSelectElement).value)"><option value="">全部有效门店</option><option value="1">营业中</option><option value="-1">已停业</option><option value="2">回收站</option></select></label><el-button :disabled="model.viewLocked()" @click="screen.reset">重置查询</el-button></div>
        <p class="hint">共 {{ state.snapshot?.count ?? 0 }} 项，当前范围 {{ visible.length }} 项。每页20项，回收站资料仍会保留。</p>
        <p v-if="state.loading" role="status">正在读取提货点目录…</p>
        <div v-if="state.snapshot && !state.loading" class="store-rows" aria-label="提货点列表"><article v-for="item in rows" :key="item.key" class="store-row"><div class="store-info"><div class="identity"><img v-if="storePreview(item.row.image_preview)" class="store-thumbnail" :src="storePreview(item.row.image_preview)" :alt="`${item.row.name}门店图片`" /><div><strong>{{ item.row.name || '未命名历史门店' }}</strong><p>#{{ item.row.id }} · {{ item.row.is_del !== 0 ? '回收站' : item.row.is_show === 1 ? '营业中' : item.row.is_show === 0 ? '已停业' : `历史营业状态 ${item.row.is_show}` }}</p></div></div><p>{{ item.row.phone }} · {{ item.row.address }} {{ item.row.detailed_address }}</p><p>营业时间 {{ item.row.day_time || '未填写' }} · 有效距离 {{ item.row.valid_range }} 米</p><p>{{ item.row.introduction || '未填写简介' }}</p></div><div v-if="canManage" class="actions"><el-button :disabled="!model.writable() || !!state.editor" @click="item.edit">编辑提货点</el-button><el-button v-if="item.row.is_del === 0" :disabled="!model.writable() || !!state.editor" @click="item.show">{{ item.row.is_show === 1 ? '设为停业' : '设为营业' }}</el-button><el-button :type="item.row.is_del === 0 ? 'danger' : 'success'" plain :disabled="!model.writable() || !!state.editor" @click="item.remove">{{ item.row.is_del === 0 ? '回收提货点' : '恢复提货点' }}</el-button></div></article><p v-if="!visible.length" class="hint empty">没有符合条件的提货点</p></div>
        <nav class="actions pagination" aria-label="提货点分页"><span>第 {{ state.filters.page }} / {{ pageCount }} 页</span><el-button :disabled="model.viewLocked() || state.filters.page <= 1" @click="screen.previous">上一页提货点</el-button><el-button :disabled="model.viewLocked() || state.filters.page >= pageCount" @click="screen.next">下一页提货点</el-button></nav>
      </template>
    </section>
    <el-dialog v-for="editor in editors" :key="editor.key" class="store-author-dialog" top="16px" :model-value="true" :title="state.editor?.row ? '编辑提货点' : '新增提货点'" width="min(760px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false" :destroy-on-close="true">
      <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" />
      <div class="editor-fields"><label v-for="field in editor.fields" :key="field.key">{{ labels[field.field] }}<textarea v-if="field.field === 'introduction'" :value="field.value" aria-label="门店简介" rows="3" :disabled="editorLocked" @input="field.set(($event.target as HTMLTextAreaElement).value)" /><select v-else-if="field.field === 'is_show' || field.field === 'is_store'" :value="field.value" :aria-label="labels[field.field]" :disabled="editorLocked" @change="field.set(Number(($event.target as HTMLSelectElement).value))"><option :value="0">{{ field.field === 'is_show' ? '停业' : '关闭' }}</option><option :value="1">{{ field.field === 'is_show' ? '营业' : '开启' }}</option><option v-if="![0,1].includes(Number(field.value))" :value="field.value">保留历史值 {{ field.value }}</option></select><input v-else-if="field.field === 'valid_range'" type="number" :value="field.value" :aria-label="labels[field.field]" :min="Math.min(0, Number(field.value))" max="2147483647" step="1" :disabled="editorLocked" @input="field.set(Number(($event.target as HTMLInputElement).value))" /><input v-else :value="field.value" :aria-label="labels[field.field]" :disabled="editorLocked" @input="field.set(($event.target as HTMLInputElement).value)" /></label>
        <fieldset><legend>区域</legend><p class="reference" aria-label="原区域名称路径">{{ editor.address.value || '未选择地区' }}</p><el-button :disabled="editorLocked" @click="editor.address.open">选择省市区</el-button></fieldset>
        <fieldset><legend>营业时间</legend><p class="reference">保存值：{{ editor.draft.day_time || '未填写' }}</p><div class="time-fields"><label v-for="time in editor.times" :key="time.key">{{ time.index === 0 ? '开始时间' : '结束时间' }}<input type="time" step="1" :value="time.value" :aria-label="time.index === 0 ? '营业开始时间' : '营业结束时间'" :disabled="editorLocked" @input="time.set(($event.target as HTMLInputElement).value)" /></label></div><small>历史时间保留原值；显式修改后按 HH:mm:ss 保存。</small></fieldset>
        <fieldset v-for="image in editor.images" :key="image.key"><legend>门店图片</legend><img v-if="image.preview" class="editor-image" :src="image.preview" alt="门店图片预览" @error="image.error" /><p v-else class="hint">原图片暂不可预览，可保留原值或重新选择。</p><p class="reference">{{ image.reference || '未选择图片' }}</p><el-button :disabled="editorLocked" @click="image.open">选择门店图片</el-button></fieldset>
        <fieldset><legend>地图选点</legend><p class="hint">也可直接填写上方经纬度。地图候选需要确认后才会写入；不会覆盖区域和详细地址。</p><el-button :disabled="editorLocked" @click="editor.map">查找位置</el-button></fieldset>
      </div><template #footer><el-button :disabled="editorLocked" @click="editor.cancel">取消编辑提货点</el-button><el-button type="primary" :disabled="editorLocked" @click="editor.submit">核对提货点保存</el-button></template>
    </el-dialog>
    <el-dialog v-for="picker in pickers" :key="picker.key" class="store-author-dialog" top="16px" :model-value="true" title="选择门店图片" width="min(820px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="picker.error" :title="picker.error" type="error" :closable="false" /><div class="picker-filters"><label>图片分类<select :value="picker.pid" aria-label="门店图片分类" @change="picker.category(Number(($event.target as HTMLSelectElement).value))"><option :value="0">未分类</option><option v-for="category in picker.categories" :key="category.id" :value="category.id">{{ category.name }} #{{ category.id }}</option></select></label><label>图片名称<input :value="picker.name" aria-label="门店图片名称" @input="picker.nameChange(($event.target as HTMLInputElement).value)" /></label><el-button @click="picker.search">查询门店图片</el-button></div><p v-if="picker.loading" role="status">正在读取图片…</p><div class="image-options"><button v-for="item in picker.items" :key="item.key" type="button" class="store-image-option" :aria-label="`选择图片 ${item.real_name}`" :disabled="picker.loading" @click="item.choose"><img :src="item.preview" :alt="item.real_name" /><span>{{ item.real_name }}</span></button><p v-if="!picker.loading && !picker.items.length">没有可选图片</p></div><template #footer><div class="actions"><span>共 {{ picker.count }} 项 · 第 {{ picker.page }} 页</span><el-button :disabled="picker.loading || picker.page <= 1" @click="picker.previous">上一页门店图片</el-button><el-button :disabled="picker.loading || picker.page * 20 >= picker.count" @click="picker.next">下一页门店图片</el-button><el-button @click="picker.close">返回提货点编辑</el-button></div></template></el-dialog>
    <el-dialog v-for="region in regions" :key="region.key" class="store-author-dialog" top="16px" :model-value="true" title="选择区域名称路径" width="min(620px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="region.error" :title="region.error" type="error" :closable="false" /><p v-if="region.loading" role="status">正在读取完整省市区…</p><div class="region-fields"><label v-for="level in region.levels" :key="level.key">{{ ['省级','市级','区级'][level.index] }}<select :aria-label="['选择省级','选择市级','选择区级'][level.index]" :value="level.value" :disabled="region.loading || !level.options.length" @change="level.set(Number(($event.target as HTMLSelectElement).value))"><option :value="0">请选择</option><option v-for="option in level.options" :key="option.id" :value="option.id">{{ option.name }}</option></select></label></div><p>{{ region.path || '请选择地区路径的末级；天然浅层叶节点可以直接确认。' }}</p><template #footer><el-button @click="region.close">取消区域选择</el-button><el-button type="primary" :disabled="region.loading || !region.ready" @click="region.confirm">确认区域</el-button></template></el-dialog>
    <el-dialog v-for="map in maps" :key="map.key" class="store-author-dialog store-map-dialog" top="16px" :model-value="true" title="地图查找位置" width="min(920px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="map.error" :title="map.error" type="warning" :closable="false" /><p v-if="map.loading" role="status">正在读取地图配置…</p><iframe v-if="map.url" :key="map.key" :ref="element => bindFrame(map.key, element)" class="location-frame" :src="map.url" title="腾讯地图选点" referrerpolicy="strict-origin-when-cross-origin" /><p v-if="map.candidate" class="reference">候选位置：{{ map.candidate.lat }}, {{ map.candidate.lng }}</p><template #footer><el-button @click="map.close">关闭地图</el-button><el-button type="primary" :disabled="map.loading || !map.candidate" @click="map.confirm">确认地图位置</el-button></template></el-dialog>
    <el-dialog v-for="confirmation in confirmations" :key="confirmation.key" class="store-author-dialog" top="16px" :model-value="true" title="确认提货点操作" width="min(560px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><p>{{ operationLabels[confirmation.operation] }}<span v-if="confirmation.id"> #{{ confirmation.id }}</span></p><p v-if="confirmation.operation === 'create' || confirmation.operation === 'update'">{{ confirmation.payload.name }} · {{ confirmation.payload.phone }}</p><p v-if="confirmation.operation === 'show'">营业状态会同步关联的有效店员状态。</p><p v-if="confirmation.operation === 'delete'">回收会同时停业并回收关联店员。存在待处理订单时将拒绝操作，原资料继续保留。</p><p v-if="confirmation.operation === 'restore'">恢复提货点并恢复关联回收店员；营业状态仍保留当前值，请另行确认。</p><template #footer><el-button :disabled="state.busy" @click="confirmation.cancel">取消提货点操作</el-button><el-button type="primary" :disabled="state.busy" @click="confirmation.confirm">确认提货点提交</el-button></template></el-dialog>
  </main>
</template>

<script setup lang="ts">
import { computed, reactive, watch, onMounted, onBeforeUnmount, type ComponentPublicInstance } from 'vue';
import { useRoute } from 'vue-router';
import { useAuthStore } from '@/stores/auth';
import { getAdminSession, getToken } from '@/utils/auth';
import { apiStoreAuthorCatalog, apiStoreAuthorCommit, apiStoreAuthorReceipt, apiStoreAuthorResolve, apiStoreAuthorCategories, apiStoreAuthorOptions, apiStoreAuthorRegions, apiStoreAuthorMapConfig } from '@/api/storeAuthor';
import { storeAuthorState } from '@/utils/storeAuthorState';
import { storePreview, type StoreAction, type StoreOperation, type StoreValues } from '../../../../common/storeAuthor';

const props = defineProps<{ active: boolean }>();
const emit = defineEmits<{ changed: [] }>();
const auth = useAuthStore(), route = useRoute();
let alive = false, generation = 0, syncing = false, queued = false;
const allowed = (values: string[]) => auth.uniqueAuth.some(p => p === '*' || p === 'store.*' || values.includes(p));
const canView = computed(() => props.active && !!auth.token && auth.token === getToken() && !!auth.userInfo && (auth.userInfo.level === 0 || allowed(['store.view', 'store.manage'])));
const canManage = computed(() => canView.value && (auth.userInfo?.level === 0 || allowed(['store.manage'])));
const prefix = (actor: number) => `cinashop_store_pending_v1_${actor}_`;
function keys(actor: number) { const result: string[] = []; for (let i = 0; i < localStorage.length; i++) { const key = localStorage.key(i); if (key?.startsWith(prefix(actor))) result.push(key); } return result.sort(); }
const model = storeAuthorState({ identity: () => `${generation}:${auth.token}:${auth.userInfo?.id}`, actor: () => auth.userInfo?.id ?? 0,
  view: () => canView.value, manage: () => canManage.value, read: apiStoreAuthorCatalog, write: apiStoreAuthorCommit, receipt: apiStoreAuthorReceipt, resolve: apiStoreAuthorResolve,
  categories: apiStoreAuthorCategories, options: apiStoreAuthorOptions, regions: apiStoreAuthorRegions, mapConfig: apiStoreAuthorMapConfig, changed: () => emit('changed'),
  readPending: actor => { const key = keys(actor)[0]; if (!key) return null; const raw = localStorage.getItem(key); if (!raw || raw.length > 512 * 1024) throw Error('原提货点操作记录异常，请保留核对'); const a = JSON.parse(raw); if (key !== prefix(actor) + a?.operation_id) throw Error('原提货点操作标识不一致'); return a; },
  persist: (actor: number, a: StoreAction | null, expected?: StoreAction) => {
    const value = a ?? expected; if (!value) throw Error('缺少原提货点操作'); const key = prefix(actor) + value.operation_id, raw = localStorage.getItem(key);
    if (a) { const text = JSON.stringify(a); if (text.length > 512 * 1024 || keys(actor).some(k => k !== key) || raw && raw !== text) throw Error('本账号已有其它未确认提货点操作'); localStorage.setItem(key, text); }
    else { if (raw && raw !== JSON.stringify(expected)) throw Error('原提货点操作记录已变化，无法清除'); localStorage.removeItem(key); }
  },
}, v => reactive(v) as typeof v);
const state = model.state;
const screens = computed(() => [model.screen()]), editors = computed(() => model.editorControls()), pickers = computed(() => model.pickerControls());
const regions = computed(() => model.regionControls()), maps = computed(() => model.mapControls()), confirmations = computed(() => model.confirmationControls());
const visible = computed(() => model.visible()), pageCount = computed(() => model.pageCount());
const rows = computed(() => visible.value.slice((state.filters.page - 1) * 20, state.filters.page * 20).map(model.rowControls));
const editorLocked = computed(() => !model.writable() || !!state.picker || !!state.region || !!state.map);
const labels: Record<keyof StoreValues, string> = { name: '门店名称', introduction: '门店简介', phone: '联系电话', address: '省市区', detailed_address: '详细地址', latitude: '纬度', longitude: '经度', day_time: '营业时间', image: '门店图片', valid_range: '有效距离（米）', is_show: '营业状态', is_store: '允许自提' };
const operationLabels: Record<StoreOperation, string> = { create: '新增提货点', update: '保存提货点', show: '调整营业状态及有效店员', delete: '回收提货点与关联店员', restore: '恢复提货点与关联店员' };
const frames = new Map<string, HTMLIFrameElement>();
function bindFrame(key: string, element: Element | ComponentPublicInstance | null) { if (element) frames.set(key, element as HTMLIFrameElement); else frames.delete(key); }
let removeMessage = () => {};
watch(() => state.map, () => {
  removeMessage(); frames.clear(); const control = model.mapControls()[0]; if (!control) return;
  const listener = (event: MessageEvent) => control.receive(event, frames.get(control.key)?.contentWindow ?? null);
  window.addEventListener('message', listener); removeMessage = () => window.removeEventListener('message', listener);
}, { flush: 'sync' });
function schedule() {
  if (!alive || syncing) return; generation++; model.dispose(); if (queued) return; queued = true;
  queueMicrotask(() => { queued = false; if (alive && props.active) void model.activate(); });
}
function syncStored(event?: Event) {
  if (syncing || event instanceof StorageEvent && event.key !== null && !['admin_token', 'admin_session'].includes(event.key) && !event.key.startsWith('cinashop_store_pending_v1_')) return;
  syncing = true; generation++; model.dispose(); const session = getAdminSession();
  auth.$patch({ token: getToken() ?? '', userInfo: session?.userInfo ?? null, menus: (session?.menus as typeof auth.menus) ?? [], uniqueAuth: session?.uniqueAuth ?? [] }); syncing = false; schedule();
}
watch(() => [auth.token, auth.userInfo, auth.uniqueAuth, auth.menus], schedule, { deep: true, flush: 'sync' });
watch(() => route.fullPath, schedule, { flush: 'sync' }); watch(() => props.active, schedule, { flush: 'sync' });
const stopAction = auth.$onAction(({ name, after }) => { if (name === 'login' || name === 'logout') after(schedule); });
onMounted(() => { alive = true; window.addEventListener('storage', syncStored); window.addEventListener('admin-session-changed', syncStored); window.addEventListener('admin-auth-expired', syncStored); syncStored(); });
onBeforeUnmount(() => { alive = false; generation++; stopAction(); model.dispose(); removeMessage(); frames.clear(); window.removeEventListener('storage', syncStored); window.removeEventListener('admin-session-changed', syncStored); window.removeEventListener('admin-auth-expired', syncStored); });
</script>

<style scoped>
.store-author,.store-author>section{display:grid;gap:16px;min-width:0}.heading,.actions,.identity{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.heading{justify-content:space-between}.heading h2{font-size:20px;margin:0}.heading p,.hint,.store-info p,small{color:var(--el-text-color-secondary);font-size:13px;line-height:1.7;margin:6px 0}.filters,.picker-filters{display:grid;grid-template-columns:minmax(180px,1fr) 180px auto;gap:12px;align-items:end}.filters label,.editor-fields label,.picker-filters label,.region-fields label{display:grid;gap:8px;font-size:14px}.editor-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:12px}.editor-fields>fieldset,.editor-fields>label:has(textarea){grid-column:1/-1}input,select,textarea{box-sizing:border-box;max-width:100%;width:100%;min-width:0;border:1px solid var(--el-border-color);border-radius:4px;background:var(--el-bg-color);color:var(--el-text-color-primary);font:inherit;padding:9px 12px}input:focus,select:focus,textarea:focus{outline:2px solid var(--el-color-primary);outline-offset:1px}input:disabled,select:disabled,textarea:disabled{opacity:.6}fieldset{border:1px solid var(--el-border-color);border-radius:6px;padding:12px;min-width:0}legend{font-size:14px;padding:0 6px}.reference{font-size:12px;overflow-wrap:anywhere}.editor-image{width:140px;max-width:100%;height:100px;object-fit:contain}.store-thumbnail{width:72px;height:60px;object-fit:contain}.store-rows{border:1px solid var(--el-border-color);border-radius:6px}.store-row{display:flex;justify-content:space-between;gap:16px;padding:16px}.store-row+.store-row{border-top:1px solid var(--el-border-color-lighter)}.store-info{min-width:0;overflow-wrap:anywhere}.actions .el-button+.el-button{margin-left:0}.pagination{justify-content:flex-end;font-size:13px}.empty{padding:20px}.image-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:16px}.store-image-option{display:grid;gap:8px;min-width:0;padding:8px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color);cursor:pointer;overflow-wrap:anywhere}.store-image-option img{width:100%;height:80px;object-fit:contain}.store-image-option:focus{outline:2px solid var(--el-color-primary)}.time-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.region-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.location-frame{width:100%;height:clamp(240px,58dvh,520px);border:0;display:block}.store-author :deep(.el-overlay-dialog){overflow:clip}.store-author :deep(.store-author-dialog){max-height:calc(100dvh - 32px);display:flex;flex-direction:column}.store-author :deep(.store-author-dialog .el-dialog__body){min-height:0;overflow:auto}.store-author :deep(.store-author-dialog .el-dialog__header),.store-author :deep(.store-author-dialog .el-dialog__footer){flex-shrink:0}.store-author :deep(.el-alert__content){min-width:0;overflow-wrap:anywhere}@media(max-width:760px){.store-row{flex-direction:column}.filters{grid-template-columns:1fr 160px}.image-options{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:480px){.filters,.picker-filters,.editor-fields,.region-fields{grid-template-columns:1fr}.heading>.actions{width:100%}.store-row{padding:12px}.pagination{justify-content:flex-start}.time-fields{grid-template-columns:1fr}.image-options{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
